// Record gnc_engine (16 bytes) at byte offset `o` of the user data.
function decodeGncEngine(dv, o) {
  return {
    on: dv.getUint8(o) !== 0,
    throttle: dv.getFloat32(o + 4, false),
    pitch: dv.getFloat32(o + 8, false),
    yaw: dv.getFloat32(o + 12, false),
  };
}

// Record engine_power (12 bytes) at byte offset `o` of the user data.
function decodeEnginePower(dv, o) {
  return {
    on: dv.getUint8(o) !== 0,
    state: dv.getUint8(o + 1),
    valid: dv.getUint8(o + 2) !== 0,
    command: dv.getFloat32(o + 4, false),
    throttle: dv.getFloat32(o + 8, false),
  };
}

// Record feedback_engine (12 bytes) at byte offset `o` of the user data.
function decodeFeedbackEngine(dv, o) {
  return {
    valid: dv.getUint8(o) !== 0,
    pitch: dv.getFloat32(o + 4, false),
    yaw: dv.getFloat32(o + 8, false),
  };
}

// 0x100 FSW status (20 bytes).
export function decodeFswStatus(dv) {
  const flags = dv.getUint8(1);
  return {
    mode: dv.getUint8(0),
    flags,
    enginesOn: (flags & 1) !== 0,
    navValid: (flags & 2) !== 0,
    translating: (flags & 4) !== 0,
    aligned: (flags & 8) !== 0,
    gnssReady: (flags & 16) !== 0,
    gnssFixCount: dv.getUint16(2, false),
    cycleCount: dv.getUint32(4, false),
    timeInMode: dv.getFloat32(8, false),
    propellant: dv.getFloat32(12, false),
    mass: dv.getFloat32(16, false),
  };
}

// 0x101 Mission config (36 bytes).
export function decodeMissionConfig(dv) {
  return {
    targetLatitude: dv.getFloat64(0, false),
    targetLongitude: dv.getFloat64(8, false),
    targetHeight: dv.getFloat64(16, false),
    targetAltitude: dv.getFloat32(24, false),
    alignTolerance: dv.getFloat32(28, false),
    translateAltitude: dv.getFloat32(32, false),
  };
}

// 0x110 Navigation (116 bytes).
export function decodeNavigation(dv) {
  return {
    attitude: [dv.getFloat32(0, false), dv.getFloat32(4, false), dv.getFloat32(8, false), dv.getFloat32(12, false)],
    angularRate: [dv.getFloat32(16, false), dv.getFloat32(20, false), dv.getFloat32(24, false)],
    specificForce: [dv.getFloat32(28, false), dv.getFloat32(32, false), dv.getFloat32(36, false)],
    altitude: dv.getFloat32(40, false),
    verticalVelocity: dv.getFloat32(44, false),
    altimeterRange: dv.getFloat32(48, false),
    altimeterValid: dv.getUint8(52) !== 0,
    east: dv.getFloat32(56, false),
    north: dv.getFloat32(60, false),
    velocityEast: dv.getFloat32(64, false),
    velocityNorth: dv.getFloat32(68, false),
    accelBiasEast: dv.getFloat32(72, false),
    accelBiasNorth: dv.getFloat32(76, false),
    positionSigmaEast: dv.getFloat32(80, false),
    positionSigmaNorth: dv.getFloat32(84, false),
    velocitySigmaEast: dv.getFloat32(88, false),
    velocitySigmaNorth: dv.getFloat32(92, false),
    gnssInnovationEast: dv.getFloat32(96, false),
    gnssInnovationNorth: dv.getFloat32(100, false),
    altimeterInnovation: dv.getFloat32(104, false),
    gnssUpdateAge: dv.getFloat32(108, false),
    altimeterUpdateAge: dv.getFloat32(112, false),
  };
}

// 0x120 Guidance and control (84 bytes).
export function decodeGuidanceControl(dv) {
  return {
    altitudeSetpoint: dv.getFloat32(0, false),
    velocitySetpoint: dv.getFloat32(4, false),
    eastSetpoint: dv.getFloat32(8, false),
    northSetpoint: dv.getFloat32(12, false),
    eastAccelCommand: dv.getFloat32(16, false),
    northAccelCommand: dv.getFloat32(20, false),
    attitudeError: [dv.getFloat32(24, false), dv.getFloat32(28, false), dv.getFloat32(32, false)],
    engines: [decodeGncEngine(dv, 36), decodeGncEngine(dv, 52), decodeGncEngine(dv, 68)],
  };
}

// 0x130 Actuator feedback (36 bytes).
export function decodeActuatorFeedback(dv) {
  return {
    engines: [decodeFeedbackEngine(dv, 0), decodeFeedbackEngine(dv, 12), decodeFeedbackEngine(dv, 24)],
  };
}

// 0x150 Engine status (72 bytes).
export function decodeEngineStatus(dv) {
  return {
    engines: [decodeEnginePower(dv, 0), decodeEnginePower(dv, 12), decodeEnginePower(dv, 24), decodeEnginePower(dv, 36), decodeEnginePower(dv, 48), decodeEnginePower(dv, 60)],
  };
}

// 0x140 GNSS (56 bytes).
export function decodeGnss(dv) {
  return {
    fixType: dv.getUint8(0),
    satellitesUsed: dv.getUint8(1),
    satellitesVisible: dv.getUint8(2),
    fixTime: dv.getFloat64(4, false),
    latitude: dv.getFloat64(12, false),
    longitude: dv.getFloat64(20, false),
    height: dv.getFloat64(28, false),
    velocity: [dv.getFloat32(36, false), dv.getFloat32(40, false), dv.getFloat32(44, false)],
    horizontalSigma: dv.getFloat32(48, false),
    verticalSigma: dv.getFloat32(52, false),
  };
}

// 0x160 Catch status (40 bytes).
export function decodeCatchStatus(dv) {
  const flags = dv.getUint8(3);
  return {
    phase: dv.getUint8(0),
    abortReason: dv.getUint8(1),
    armsExpected: dv.getUint8(2),
    flags,
    go: (flags & 1) !== 0,
    positionOk: (flags & 2) !== 0,
    speedOk: (flags & 4) !== 0,
    tiltOk: (flags & 8) !== 0,
    rtkOk: (flags & 16) !== 0,
    corridorOk: (flags & 32) !== 0,
    aborted: (flags & 64) !== 0,
    alongRemaining: dv.getFloat32(4, false),
    lateralError: dv.getFloat32(8, false),
    pinHeightAboveSeat: dv.getFloat32(12, false),
    alongSpeed: dv.getFloat32(16, false),
    lateralSpeed: dv.getFloat32(20, false),
    sinkRate: dv.getFloat32(24, false),
    tilt: dv.getFloat32(28, false),
    lateralLimit: dv.getFloat32(32, false),
    timeToSeat: dv.getFloat32(36, false),
  };
}

// 0x161 Catch config (80 bytes).
export function decodeCatchConfig(dv) {
  return {
    landingMode: dv.getUint8(0),
    seatPoint: [dv.getFloat32(4, false), dv.getFloat32(8, false), dv.getFloat32(12, false)],
    approachDir: [dv.getFloat32(16, false), dv.getFloat32(20, false)],
    stagingDistance: dv.getFloat32(24, false),
    towerPosition: [dv.getFloat32(28, false), dv.getFloat32(32, false)],
    mastHalfWidth: dv.getFloat32(36, false),
    mastHeight: dv.getFloat32(40, false),
    hingeHalfSpacing: dv.getFloat32(44, false),
    hingeSetback: dv.getFloat32(48, false),
    armLength: dv.getFloat32(52, false),
    armOpenAngle: dv.getFloat32(56, false),
    armClosedAngle: dv.getFloat32(60, false),
    windowLateral: dv.getFloat32(64, false),
    windowAlong: dv.getFloat32(68, false),
    windowSink: dv.getFloat32(72, false),
    windowTilt: dv.getFloat32(76, false),
  };
}

// Decoders and user data lengths by APID.
export const DECODERS = {
  0x100: decodeFswStatus,
  0x101: decodeMissionConfig,
  0x110: decodeNavigation,
  0x120: decodeGuidanceControl,
  0x130: decodeActuatorFeedback,
  0x150: decodeEngineStatus,
  0x140: decodeGnss,
  0x160: decodeCatchStatus,
  0x161: decodeCatchConfig,
};
export const USER_LENGTH = {
  0x100: 20,
  0x101: 36,
  0x110: 116,
  0x120: 84,
  0x130: 36,
  0x150: 72,
  0x140: 56,
  0x160: 40,
  0x161: 80,
};
